// THE TURN'S OUTBOUND MESSAGES, IN ORDER — and there may be more than one now.
//
// This was `runOnceForEachItem` and emitted exactly one text body. A product list is
// SEVERAL messages (a sentence, then cards, then "See more"), and they are composed by
// jovi-mall rather than here: `channel-reply.ts` is the one place that knows a WhatsApp
// reply-button title is capped at twenty characters and that a carousel is a template with
// a fixed card count. What arrives here is a ready array of request bodies.
//
// ⚠ ORDER IS THE RENDERING. The sentence goes first, then the cards. `send guard`,
// `is telegram?` and both send nodes iterate their input items in order, so emitting the
// array is all it takes — do not sort it, do not fan it out.
//
// ⚠ Reads `$('AI Agent')` explicitly rather than `$input`. Its immediate predecessor is now
// a Redis DELETE, whose output is an API result and not the model's answer.
const inbound = $('Inbound').first().json;
const sync = $('sync identity').first().json;

// ── The cards the display tool drew, if it ran ──────────────────────────────
//
// wi-mall-product-cards writes the channel-ready bodies to Redis rather than returning
// them, because a tool result lands in the MODEL's context where a sendPhoto body can do
// nothing. Same gate-echo mechanism the bargaining tools use, for the same reason.
//
// ⚠ The value carries its own `expiresAt` AND its own `__messageId`, and both are checked.
// The n8n Redis node's `set` exposes no TTL — measured, and the reason the product-search
// query cache lives in Postgres — so a key can outlive its turn. Sending last turn's cards
// under this turn's sentence is worse than sending none.
let cards = [];
try {
  const echoRaw = $('check display').first().json.displayEcho;
  const echo = echoRaw ? JSON.parse(String(echoRaw)) : null;
  const fresh = !!echo && !!echo.expiresAt && new Date(echo.expiresAt).getTime() > Date.now();
  const mine = !!echo && String(echo.__messageId || '') === String(inbound.messageId || '');
  if (echo && fresh && mine && Array.isArray(echo.replies)) {
    cards = echo.replies.filter(function (r) { return r && r.channel && r.method && r.body; });
  }
} catch (e) {
  cards = [];
}

const answer = String($('AI Agent').first().json.output ?? '').trim();

// ── The messages the assistant's TOOLS prepared, if any ─────────────────────
//
// A tool can answer with a ready channel-ready body of its own: the account-closure
// consequence with its Keep/Confirm buttons, an in-app door, a picker. Until now the customer
// never saw one. A tool's result lands in the MODEL's context, where a Telegram request body
// can do nothing at all, and this node sent only the model's sentence.
//
// They are read from the agent's OWN intermediate steps, which is what binds them to THIS
// turn: `returnIntermediateSteps` puts one entry per tool call in the agent's output, each
// carrying its `observation` -- the tool node's output items, JSON-encoded. For the MCP client
// that is [{ response: [{ type: 'text', text: '<the backend body, JSON>' }] }], so it is JSON
// inside JSON. Both layers are walked DEFENSIVELY: anything unrecognised yields no message
// rather than an exception, which degrades to exactly the behaviour before this existed.
//
// ⚠ ONLY A SUCCESSFUL call's reply is sent. A refused tool also carries a `reply` (built from
// error.customerMessage) and the model RETRIES -- relaying those would send the customer a
// refusal the model has already recovered from. A failure stays the model's to word.
//
// ⚠ Order is the rendering here too: tool messages go out in the order the model called them,
// and the product cards take the place of the display tool's own call.
const toolMessages = [];
let standsAlone = false;
const seenReply = {};
const collectReplies = function (value, depth) {
  // ⚠ The real nesting is SEVEN levels (observation string → items → response → text block →
  // string → bodies array → body), so a tighter bound silently finds nothing — and 'nothing'
  // looks exactly like 'this tool prepared no message'. Proven by the harness, which caught a
  // limit of 5 doing precisely that.
  if (value == null || depth > 12) { return; }
  if (typeof value === 'string') {
    let parsed = null;
    try { parsed = JSON.parse(value); } catch (e) { parsed = null; }
    if (parsed != null && typeof parsed === 'object') { collectReplies(parsed, depth + 1); }
    return;
  }
  if (Array.isArray(value)) { value.forEach(function (v) { collectReplies(v, depth + 1); }); return; }
  if (typeof value !== 'object') { return; }
  if (Array.isArray(value.response)) { collectReplies(value.response, depth + 1); return; }
  if (value.type === 'text' && typeof value.text === 'string') { collectReplies(value.text, depth + 1); return; }
  if (value.success !== true) { return; }
  const list = (Array.isArray(value.replies) && value.replies.length > 0) ? value.replies : (value.reply ? [value.reply] : []);
  list.forEach(function (reply) {
    if (!reply || !reply.channel || !reply.method || !reply.body) { return; }
    const key = JSON.stringify(reply);
    if (seenReply[key]) { return; }
    seenReply[key] = true;
    if (value.replyStandsAlone === true) { standsAlone = true; }
    toolMessages.push({ reply: reply, isDisplay: false });
  });
};

const steps = $('AI Agent').first().json.intermediateSteps;
if (Array.isArray(steps)) {
  steps.forEach(function (step) {
    const tool = String((step && step.action && step.action.tool) || '');
    // The display tool echoes its cards through Redis rather than returning them, so its
    // place in the order is all that is read from its step.
    if (/show.?products/i.test(tool)) { toolMessages.push({ reply: null, isDisplay: true }); return; }
    collectReplies(step && step.observation, 0);
  });
}

// § 6 · The file the customer sent can itself carry a question ('which request is this for?').
// It is the BACKEND's question and not a tool's: `upload inbound file` is called by this
// workflow, not by the model, so it has no step of its own to be found in. Same rules —
// successful answers only, same de-duplication, and it lands after the agent's sentence.
if ($('upload inbound file').isExecuted) {
  collectReplies($('upload inbound file').first().json, 0);
}
const toolReplyCount = toolMessages.filter(function (m) { return !m.isDisplay; }).length;

// ⚠ The stand-in is SUPPRESSED when there are cards. An empty model turn is a failure only
// when nothing else is going out; over a page of products it would put "Sorry, I could not
// answer that just now" above five things we had just found for them.
// ⚠ A TOOL MESSAGE SUPPRESSES THE STAND-IN for the same reason a card does: 'Sorry, I could
// not answer that just now' above an answer the platform did produce is worse than silence.
const standIn = (cards.length > 0 || toolReplyCount > 0)
  ? ''
  : String(sync && sync.data && sync.data.fallback ? sync.data.fallback.assistantUnavailable : '').trim();

// ⚠ THE MODEL WRITES MARKDOWN AND NEITHER CHANNEL RENDERS IT. The send nodes set no
// parse_mode, and deliberately: Telegram REFUSES a message whose formatting does not balance,
// and a refused send is a customer who gets nothing. So `**Closed**` reached the customer as a
// word between four literal asterisks, on both channels (owner's handset, 2026-09-21).
// WhatsApp's own bold is ONE asterisk each side; Telegram without parse_mode has no bold at all.
// The prompt asks for no markdown as well -- this is the half that does not depend on the model
// doing as it is told.
//
// ⚠ Only the SENTENCE is rewritten. Tool messages and cards are the backend's, already
// rendered for their channel, and are never touched here.
// ⚠ Character classes, not escapes, on purpose: this body travels through JSON to reach n8n,
// and a backslash is the one character that has gone missing on that trip before.
const plainFor = function (s) {
  const whatsapp = inbound.channel !== 'telegram';
  return String(s)
    .replace(/[*][*]([^*]+?)[*][*]/g, whatsapp ? '*$1*' : '$1')
    .replace(/^#{1,6} +/gm, '');
};

const chosen = plainFor(answer || standIn);
const text = chosen.length > 4000 ? chosen.slice(0, 3997) + '…' : chosen;

// ⚠ EVERY ITEM CARRIES ITS ROLE from here on. `drop duplicate reply` suppresses the AGENT'S
// SENTENCE on a bargained turn, and it used to find it by POSITION (item 0) -- true while the
// only other items were cards. A tool message can now precede or follow it, so position is no
// longer the sentence's identity and the role says which item is which.
//
// `standsAlone` is the backend's own flag on a tool answer whose message must be the whole
// turn (the account-closure consequence: a paraphrase of it is the failure). n8n holds no
// list of tool names -- the flag travels with the answer.
const out = [];

if (text && !standsAlone) {
  out.push({ json: { role: answer ? 'model' : 'standIn', reply: inbound.channel === 'telegram'
    ? { channel: 'telegram', method: 'sendMessage', body: { chat_id: String(inbound.externalId), text: text } }
    : { channel: 'whatsapp', method: 'messages', body: {
        messaging_product: 'whatsapp', recipient_type: 'individual',
        to: String(inbound.externalId), type: 'text', text: { body: text } } } } });
}

let cardsEmitted = false;
const emitCards = function () {
  if (cardsEmitted) { return; }
  cardsEmitted = true;
  cards.forEach(function (reply) { out.push({ json: { role: 'card', reply: reply } }); });
};
toolMessages.forEach(function (m) {
  if (m.isDisplay) { emitCards(); return; }
  out.push({ json: { role: 'tool', reply: m.reply } });
});
emitCards();

// `send guard` drops a null reply. Emitting one item rather than none keeps this branch the
// exact shape it has always been for a turn with nothing to say.
if (out.length === 0) { out.push({ json: { reply: null } }); }

return out;

// What the model is actually asked, for an ordinary agent turn.
//
// ⚠ THIS USED TO SAY THE MODEL COULD NOT SEE THE FILE, AND THAT IS NO LONGER TRUE.
// wi-mall-perceive renders a picture, a voice note or a video into text before we get
// here. Three different things come back and they are NOT interchangeable:
//
//   audio  -> a TRANSCRIPT. That IS the customer's message, so it becomes the turn
//             itself rather than a note about a turn.
//   image  -> a DESCRIPTION written by another model. The agent still cannot see, so it
//    video    must speak only about what the description mentions and never claim to
//             have looked at it.
//
// Perceiving and STORING are separate questions and separate branches. A voice note is
// understood and never uploaded, because the backend allowlist is images and PDF only.
const inbound = $('Inbound').item.json;
const typed = String(inbound.text || '').trim();

let note = '';
let spoken = '';

// Referencing a node that did not run in this execution THROWS, so ask first.
if (inbound.kind === 'media' && $('call perceive').isExecuted) {
  const p = $('call perceive').item.json || {};
  const body = (p && p.perceived === true) ? String(p.text || '').trim() : '';

  if (body && p.kind === 'audio') {
    spoken = body;
    note = '[The customer sent this as a VOICE NOTE. Answer it exactly as if they had typed it, in the language they spoke. Never mention transcription.]';
  } else if (body && p.kind === 'video') {
    note = '[The customer sent a VIDEO. You cannot watch it. A model that did describes it as: ' + body + ' Speak only about what that description mentions, and never claim to have watched it.]';
  } else if (body) {
    note = '[The customer sent a PICTURE. You cannot see it. A model that did describes it as: ' + body + ' Speak only about what that description mentions, and never claim to have seen it.]';
  } else {
    note = '[The customer sent a file and it could not be read. Say so plainly and ask them to describe it, or to send it again.]';
  }
}

// The storage handle, when the file was one the backend accepts. Only reachable through
// `is storable?`, so audio and video never land here.
if (inbound.kind === 'media' && $('upload inbound file').isExecuted) {
  const res = $('upload inbound file').item.json || {};
  const d = res.data;
  // ⚠ THE PLATFORM MAY HAVE ALREADY ASKED THE CUSTOMER WHICH REQUEST THIS FILE IS FOR, with
  // buttons (a picker it renders when they have open requests). That question is SENT this
  // turn, so the model must not spend the one-use reference racing it: whoever loses gets
  // 'send the file again'. ⏳ The exact wording is the orders stream's to confirm.
  if (res.reply) {
    note = note + ' [The customer has already been asked, with buttons, which request this file belongs to. Do not attach it yourself unless they name one in words.]';
  }
  if (res.success && d && d.ref) {
    note = note + ' [It is also stored as ' + d.fileName + ' (' + d.kind + '), reference ' + d.ref + '. Pass that exact string as ref to tickets_add_attachment if it belongs on a support ticket; open the ticket first if there is not one. The reference works ONCE and expires in 30 minutes.]';
  } else {
    // The SENTENCE is the backend's, already in the customer's language: n8n holds no
    // copy table and no translator. See api-doc/n8n/bot-surface.md 11.4.
    const msg = res.error ? String(res.error.customerMessage || '').trim() : '';
    if (msg) {
      note = note + ' [It could not be stored. If they ask to attach it to anything, tell them exactly this, in their language: ' + msg + ']';
    }
  }
}

const agentInput = [note, typed || spoken].filter(Boolean).join(' ').trim();

return { json: { agentInput: agentInput || null } };

// EVERY MESSAGE THIS TURN COMPOSED GOES OUT — AND THE MAIN AGENT'S SENTENCE IS SUPPRESSED WHEN
// THE BARGAINER HAS ALREADY SPOKEN.
//
// ── What this node is for (unchanged since the A3 fix) ───────────────────────
// `compose agent reply` emits the turn as SEVERAL items: the agent's sentence (when there is
// one), the messages its tools prepared, and each card the display tool echoed. This node
// relays them ALL, in order — it used to read `.first()` and return ONE, so every card after
// the first was silently dropped. ⚠ Never sort them: order IS the rendering.
//
// ── The bargaining suppression (unchanged in purpose) ────────────────────────
// `open_negotiation` chains into a full bargaining turn, so the customer is sent the gate's
// approved sentence from INSIDE the agent's tool call. The agent still composes a final answer
// afterwards, and without this the customer gets two messages: the negotiated price, then a
// line saying the price is being looked at. The sentence stays the BARGAINER'S (D-4).
//
// ── ⭐ WHAT CHANGED: the sentence is identified by ROLE, not by POSITION ──────
// The A3 fix found the agent's sentence at item 0 when the model had spoken, and otherwise
// compared a single item against the backend's stand-in word for word. Both were true only
// while the sentence and the cards were the only things in the list. A tool's own message can
// now sit in that list, so `compose agent reply` labels every item it emits — `model`,
// `standIn`, `card`, `tool` — and this node suppresses exactly the first two. The two fallback
// nodes emit a sentence and nothing else, and carry no label, so an unlabelled item is
// treated as the sentence it is.
//
// ⚠ What is suppressed is the AGENT'S SENTENCE — never a card, never a tool's message. A turn
// that both bargained and showed products keeps its products.
//
// The echo is written ONLY after wi-mall-bargain's send returned, is stamped with this turn's
// messageId, carries its own expiry (the n8n Redis node's `set` exposes no TTL) and is deleted
// on read. A stale, mismatched or malformed echo is not an answer.
//
// Fails toward an extra message, never toward silence: with Redis unreachable the customer
// keeps the counter-offer and also gets the bridging line.
const inbound = $('Inbound').first().json;

let source = null;
for (const nm of ['compose agent reply', 'agent fallback', 'outage fallback']) {
  if ($(nm).isExecuted) { source = nm; break; }
}
if (source == null) { return [{ json: { reply: null } }]; }

const items = $(source).all()
  .map(function (item) { return item.json || {}; })
  .filter(function (j) { return j.reply != null; });

let answered = false;
if ($('read bargain echo').isExecuted) {
  const raw = ($('read bargain echo').first().json || {}).bargainAnswered;
  try {
    const echo = raw ? JSON.parse(String(raw)) : null;
    const live = !!echo && !!echo.expiresAt && new Date(echo.expiresAt).getTime() > Date.now();
    if (live && String(echo.messageId) === String(inbound.messageId)) { answered = true; }
  } catch (e) { /* a malformed echo is not an answer */ }
}

const out = answered
  ? items.filter(function (j) { return j.role === 'card' || j.role === 'tool'; })
  : items;

if (out.length === 0) { return [{ json: { reply: null } }]; }
return out.map(function (j) { return { json: { role: j.role || 'model', reply: j.reply } }; });
